#!/usr/bin/env python3
"""Build Motherlode's sections, category folders and README tables.

Run from anywhere:
    python3 .github/scripts/build_catalog.py           # create folders, rewrite READMEs
    python3 .github/scripts/build_catalog.py --prune   # also delete folders that left the list

To add, rename or move a category, edit GROUPS below and run it again.
Run it after adding a design too: it puts every design folder, with its
preview, on its category page.

It only writes README.md files. --prune deletes a folder that is no longer
listed, and only when that folder holds nothing but README.md files, so
folders with designs in them are never touched. Folders starting with
"_" or "." (like _inbox) are always left alone.
"""
import html
import re
import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SCRIPT = ".github/scripts/build_catalog.py"
MARK = f"<!-- Generated by {SCRIPT}. Edit that file, not this one. -->"
SLUG = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*$")
# What a category page shows for each design; the first file that exists wins.
PREVIEWS = ("preview.gif", "preview.webp", "preview.png", "preview.jpg", "exports/original.png")
MEDIA = {".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".mp4", ".webm", ".mov"}

