ROOT_README = """{mark}
# Motherlode

**The mother of all design libraries.**

{intro}

**[Browse it live →](https://ap0l1on.github.io/Motherlode/)** Play with every design, flip through its colorways and copy the code.

## What's inside

{inside}
## How it's organized

- Designs are sorted by what they are, not the tool they were made in. A landing page goes in `web/landing-pages/` whether it was made in Figma, Framer or code.
- If something fits more than one category, put it where people would look first.
- Missing a category? Add it to [`{script}`]({script}) and run `python3 {script}`. It rebuilds every folder and table.

## Adding a design

Every design gets its own folder inside a category, named in lowercase with dashes:

```text
dashboards/
└── analytics/
    └── neon-glass/
        ├── README.md         what it is, its colorways, fonts and credits
        ├── preview.png       the original colorway, shown on the category page
        ├── colorways.png     every colorway in one image
        ├── source/
        │   └── design.html   the design itself, with every colorway built in
        └── exports/          one file per colorway: original.png, light.png, dark.png …
```

Every design comes in several colorways. Its colors live in CSS variables, so a new colorway is just a new palette. After adding a design, run `python3 {script}` to put it on its category page.

## Big files

GitHub warns about files over 50 MB and rejects anything over 100 MB. For heavy sources like raw video or huge PSDs, use [Git LFS](https://git-lfs.com) or keep the file in shared storage and link to it from the design's README.
"""


def write(path, text):
    path.write_text(text, encoding="utf-8")


def only_readmes(folder):
    return all(f.name == "README.md" for f in folder.rglob("*") if f.is_file())


def prune():
    wanted = {sec: {cat for cat, _ in cats} for _, secs in GROUPS for sec, _, cats in secs}
    removed, kept = [], []
    for sec_dir in sorted(p for p in ROOT.iterdir() if p.is_dir() and not p.name.startswith((".", "_"))):
        if sec_dir.name not in wanted:
            stale = [sec_dir]
        else:
            stale = [c for c in sorted(sec_dir.iterdir())
                     if c.is_dir() and c.name not in wanted[sec_dir.name]]
        for folder in stale:
            (removed if only_readmes(folder) else kept).append(folder)
    for folder in removed:
        shutil.rmtree(folder)
    return removed, kept


def plural(n, word):
    return f"{n} {word}" + ("" if n == 1 else "s")


def find_designs(cat_dir, warnings):
    """Every design folder in a category, as (folder, name, preview, colorway count)."""
    found = []
    for d in sorted(p for p in cat_dir.iterdir() if p.is_dir() and not p.name.startswith((".", "_"))):
        rel = d.relative_to(ROOT)
        if not SLUG.match(d.name):
            warnings.append(f"{rel}: folder name should be lowercase with dashes")
        name = title(d.name)
        readme = d / "README.md"
        if readme.exists():
            lines = readme.read_text(encoding="utf-8").splitlines()
            name = next((l[2:].strip() for l in lines if l.startswith("# ")), name)
        else:
            warnings.append(f"{rel}: missing README.md")
        preview = next((p for p in PREVIEWS if (d / p).is_file()), None)
        if preview is None:
            warnings.append(f"{rel}: missing preview.png")
        exports = d / "exports"
        colorways = len({f.stem for f in exports.iterdir() if f.suffix.lower() in MEDIA}) if exports.is_dir() else 0
        found.append((d.name, name, preview, colorways))
    return found


def design_grid(designs):
    cells = []
    for folder, name, preview, colorways in designs:
        label = html.escape(name)
        image = (f'<a href="{folder}/"><img src="{folder}/{preview}" width="260" alt="{label}"></a><br>'
                 if preview else "")
        note = f"<br><sub>{plural(colorways, 'colorway')}</sub>" if colorways else ""
        cells.append(f'<td align="center" valign="top" width="33%">{image}'
                     f'<a href="{folder}/"><b>{label}</b></a>{note}</td>')
    rows = ["<tr>" + "".join(cells[i:i + 3]) + "</tr>" for i in range(0, len(cells), 3)]
    return "<table>\n" + "\n".join(rows) + "\n</table>"


def build():
    seen, inside, warnings = set(), [], []
    n_sections = n_categories = n_designs = 0
    for group, sections in GROUPS:
        inside += [f"### {group}", "", "| Section | Categories |", "| --- | --- |"]
        for sec, sec_desc, cats in sections:
            assert SLUG.match(sec) and sec not in seen, f"bad or duplicate section: {sec}"
            seen.add(sec)
            names = [c for c, _ in cats]
            assert len(set(names)) == len(names), f"duplicate category in {sec}"
            sec_dir = ROOT / sec
            sec_dir.mkdir(exist_ok=True)
            rows, links, sec_designs = [], [], 0
            for cat, cat_desc in cats:
                assert SLUG.match(cat), f"bad category: {sec}/{cat}"
                cat_dir = sec_dir / cat
                cat_dir.mkdir(exist_ok=True)
                designs = find_designs(cat_dir, warnings)
                if designs:
                    body = (f"Part of [{title(sec)}](../).\n\n## Designs ({len(designs)})\n\n"
                            f"{design_grid(designs)}\n\n"
                            "Adding one? See [Adding a design](../../README.md#adding-a-design).\n")
                else:
                    body = (f"Part of [{title(sec)}](../). Each design gets its own folder here. "
                            "See [Adding a design](../../README.md#adding-a-design).\n")
                write(cat_dir / "README.md", f"{MARK}\n# {title(cat)}\n\n{cat_desc}.\n\n{body}")
                count = f" · **{plural(len(designs), 'design')}**" if designs else ""
                rows.append(f"| [{title(cat)}]({cat}/) | {cat_desc}{count} |")
                links.append(f"[{title(cat)}]({sec}/{cat}/)")
                sec_designs += len(designs)
            write(sec_dir / "README.md",
                  f"{MARK}\n# {title(sec)}\n\n{sec_desc}.\n\n"
                  "| Category | What goes in it |\n| --- | --- |\n" + "\n".join(rows) + "\n\n"
                  "Each design gets its own folder inside a category. "
                  "See [Adding a design](../README.md#adding-a-design).\n")
            sec_note = f"<br><sub>{plural(sec_designs, 'design')}</sub>" if sec_designs else ""
            inside.append(f"| [**{title(sec)}**]({sec}/){sec_note} | " + " · ".join(links) + " |")
            n_sections += 1
            n_categories += len(cats)
            n_designs += sec_designs
        inside.append("")
    intro = (f"Every kind of design, for everything, in one place: {n_sections} sections and "
             f"{n_categories} categories, from logos and landing pages to dashboards, Mac menu bar "
             "apps, album covers, worksheets and tattoo designs.")
    if n_designs:
        intro += f" {plural(n_designs, 'design')} so far, each in several colorways."
    intro += " Make something once, drop it here, and nobody has to make it again."
    write(ROOT / "README.md", ROOT_README.format(
        mark=MARK, script=SCRIPT, intro=intro, inside="\n".join(inside)))
    return n_sections, n_categories, n_designs, warnings


def check_links():
    """Every relative link and image in every README must point at something that exists."""
    link = re.compile(r'\]\(([^)\s]+)\)|(?:href|src)="([^"]+)"')
    broken, readmes = [], 0
    for md in ROOT.rglob("README.md"):
        if any(p == ".git" or p.startswith("_") for p in md.relative_to(ROOT).parts):
            continue
        readmes += 1
        for found in link.findall(md.read_text(encoding="utf-8")):
            target = found[0] or found[1]
            if target.startswith(("http://", "https://", "mailto:", "#")):
                continue
            if not (md.parent / target.split("#")[0]).exists():
                broken.append(f"{md.relative_to(ROOT)} -> {target}")
    return readmes, broken


def main():
    if "--prune" in sys.argv[1:]:
        removed, kept = prune()
        for folder in removed:
            print("removed", folder.relative_to(ROOT))
        for folder in kept:
            print("KEPT, has designs in it, move them first:", folder.relative_to(ROOT))
    sections, categories, designs, warnings = build()
    readmes, broken = check_links()
    print(f"sections={sections} categories={categories} designs={designs} "
          f"readmes={readmes} broken_links={len(broken)} warnings={len(warnings)}")
    for line in warnings:
        print("WARN", line)
    for line in broken:
        print("BROKEN", line)
    sys.exit(1 if broken else 0)


if __name__ == "__main__":
    main()
